		{
			name: "Keyword",
			scope: [
				"keyword",
				"meta.property-value.keyword",
				"support.constant.property-value.keyword",
				"meta.preprocessor.keyword",
				"keyword.other.use",
				"keyword.other.function.use",
				"keyword.other.namespace",
				"keyword.other.new",
				"keyword.other.special-method",
				"keyword.other.unit",
				"keyword.other.use-as"
			],
			settings: keyword
		},
		{
			name: "Storage",
			scope: [
				"storage",
				"storage.type",
				"storage.type.ts",
				"storage.type.var.ts",
				"storage.type.js",
				"storage.type.var.js",
				"storage.type.const.ts",
				"storage.type.let.ts",
				"storage.type.let.js",
				"storage.type.const.js",
				"entity.name.tag"
			],
			settings: storage
		},
		{
			name: "Pointer, access, etc",
			scope: ["meta.ptr", "meta.pointer", "meta.address", "meta.array.cxx"],
			settings: access
		},
		{
			name: "Preprocessor",
			scope: "meta.preprocessor",
			settings: declare
		},

		{
			name: "Library",
			scope: ["support.class", "support.function", "support.constant"],
			settings: library
		},
		{
			name: "Invalid",
			scope: "invalid",
			settings: invalid
		},
		{
			name: "Invalid deprecated",
			scope: ["invalid.deprecated"],
			settings: invalid
		},
		{
			name: "Markdown Title Hash",
			scope: [
				"punctuation.definition.heading.md",
				"entity.name.type.md",
				"beginning.punctuation"
			],
			settings: declare
		},
		{
			name: "Markdown titles",
			scope: ["markup.heading", "entity.name.section"],
			settings: keyword
		},
		{
			name: "Markdown Raw",
			scope: ["markup.raw", "markup.inline.raw", "markup.fenced", "markup.fenced_code"],
			settings: quote
		},
		{
			name: "Markdown link",
			scope: [
				"markup.link",
				"string.other.link.title",
				"string.other.link.description",
				"meta.link.inline",
				"meta.image.inline"
			],
			settings: declare
		},
		{
			name: "Makefile Variables",
			scope: ["variable.language.makefile", "variable.other.makefile"],
			settings: declare
		},
		{
			scope: ["markup.italic"],
			settings: {
				fontStyle: "italic"
			}
		},
		{
			scope: ["markup.bold"],
			settings: {
				fontStyle: "bold"
			}
		},
		{
			name: "CSS Class",
			scope: ["entity.other.attribute-name.class.css"],
			settings: library
		},
		{
			name: "CSS Tag name",
			scope: ["entity.name.tag.css"],
			settings: keyword
		},
		{
			name: "CSS Property",
			scope: ["meta.property-name.css"],
			settings: declare
		}
	];

	return {
		$schema: "vscode://schemas/color-theme",
		name: themeName,
		colors: uiColors,
		tokenColors,
		semanticHighlighting: true
	};
}

